#!/usr/bin/env python3
"""Build /results/recovered.json from the live Redis instance on 127.0.0.1:6379."""
import json
import os
import socket

HOST, PORT = "127.0.0.1", 6379


class Resp:
    def __init__(self, host, port):
        self.sock = socket.create_connection((host, port))
        self.f = self.sock.makefile("rb")

    def cmd(self, *args):
        out = [b"*%d\r\n" % len(args)]
        for a in args:
            b = a.encode() if isinstance(a, str) else a
            out.append(b"$%d\r\n%s\r\n" % (len(b), b))
        self.sock.sendall(b"".join(out))
        return self._read()

    def _read(self):
        line = self.f.readline()
        if not line:
            raise EOFError("connection closed")
        tag, body = line[:1], line[1:-2]
        if tag == b"+":
            return body.decode()
        if tag == b"-":
            raise RuntimeError(body.decode())
        if tag == b":":
            return int(body)
        if tag == b"$":
            n = int(body)
            if n == -1:
                return None
            data = self.f.read(n + 2)[:-2]
            return data.decode()
        if tag == b"*":
            n = int(body)
            if n == -1:
                return None
            return [self._read() for _ in range(n)]
        raise RuntimeError("bad RESP tag %r" % tag)


def num(s):
    """Render a zset score as int when integral, else float."""
    f = float(s)
    return int(f) if f.is_integer() else f


r = Resp(HOST, PORT)
assert r.cmd("PING") == "PONG"

# Determine which logical DB holds the data (0 unless the AOF selected another).
db = 0
for line in r.cmd("INFO", "keyspace").splitlines():
    if line.startswith("db") and ":keys=" in line:
        idx = int(line[2:line.index(":")])
        if int(line.split("keys=")[1].split(",")[0]) > 0:
            db = idx
            break
if db != 0:
    r.cmd("SELECT", str(db))

keys = []
for name in sorted(r.cmd("KEYS", "*")):
    t = r.cmd("TYPE", name)
    if t == "string":
        value = r.cmd("GET", name)
    elif t == "hash":
        flat = r.cmd("HGETALL", name)
        value = {k: v for k, v in sorted(zip(flat[0::2], flat[1::2]))}
    elif t == "list":
        value = r.cmd("LRANGE", name, "0", "-1")
    elif t == "set":
        value = sorted(r.cmd("SMEMBERS", name))
    elif t == "zset":
        flat = r.cmd("ZRANGE", name, "0", "-1", "WITHSCORES")
        pairs = list(zip(flat[0::2], flat[1::2]))
        value = [
            {"member": m, "score": num(s)}
            for m, s in sorted(pairs, key=lambda p: p[0])
        ]
    elif t == "stream":
        value = []
        for entry_id, flat in r.cmd("XRANGE", name, "-", "+"):
            value.append(
                {
                    "id": entry_id,
                    "fields": {k: v for k, v in zip(flat[0::2], flat[1::2])},
                }
            )
    else:
        raise RuntimeError("unhandled type %s for key %s" % (t, name))
    keys.append({"name": name, "type": t, "value": value})

os.makedirs("/results", exist_ok=True)
with open("/results/recovered.json", "w", encoding="utf-8") as fh:
    json.dump({"db": db, "keys": keys}, fh, ensure_ascii=False, indent=2)
    fh.write("\n")

print("wrote /results/recovered.json: db=%d, %d keys" % (db, len(keys)))

